INSERT INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-02-05-sweden-special-investigator-appointed', 'en', 'Sweden appoints a special investigator to assess a domestic e-invoicing mandate', 'Sweden''s Ministry of Finance has appointed a special investigator (Dir. 2026:9) to determine how the EU''s ViDA framework should be implemented in Swedish law, and separately to assess whether e-invoicing and digital reporting should be introduced for purely domestic transactions — with findings due by 30 November 2027.', '<h3>🇸🇪 Sweden appoints a special investigator to assess a domestic e-invoicing mandate</h3>
<p>Sweden''s Ministry of Finance formally appointed a special investigator (särskild utredare) under government directive Dir. 2026:9 to examine two genuinely separate questions. The first is essentially mandatory: identifying the legislative changes needed to implement the EU''s ViDA framework for cross-border B2B digital reporting, which Sweden must transpose regardless of its own domestic preferences. The second is genuinely open — whether e-invoicing and digital reporting should also be introduced for purely domestic Swedish transactions, and if so, how far such a system should reach. Findings are due no later than 30 November 2027, timed to allow implementation ahead of the EU''s own 1 July 2030 cross-border deadline.</p>
<p>Worth understanding Sweden''s starting position clearly: unlike Norway, which has already legislated a firm 2027 domestic B2B mandate, or Denmark''s established digital bookkeeping model, Sweden has historically shown genuine reluctance to legislate any domestic e-invoicing mandate at all. This investigation follows a formal request (hemställan) submitted in 2023 by Digg, Bolagsverket, and Skatteverket jointly, and a further request from the Swedish Business and Industry Tax Delegation in July 2025 — meaning the pressure for this review came substantially from Swedish institutions and industry themselves, not purely from Brussels.</p>
<p><strong>What this means for your team:</strong> Sweden''s domestic B2B e-invoicing position remains genuinely undecided until at least late 2027 — don''t assume Sweden will follow Norway''s or Denmark''s more decisive timelines just because they''re Nordic neighbours. What is already certain is the EU cross-border requirement from 2030, so cross-border ViDA compliance planning shouldn''t wait on this domestic investigation''s outcome, even though the domestic question remains genuinely open.</p>');
INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-05-06-sweden-online-audit-powers', '2026-05-06', '2026-05', 'Sweden''s Parliament approved government proposals granting Skatteverket the power to inspect businesses'' accounting and other records directly via the internet, including records held in cloud platforms or third-party systems — a step toward system-to-system tax administration even without a formal e-invoicing mandate yet.', '<h3>🇸🇪 Parliament approves direct online access to accounting records for Skatteverket</h3>
<p>Sweden''s Parliament approved government proposals granting Skatteverket the power to inspect businesses'' accounting and other accounting material directly via the internet — including records held on cloud platforms or in third-party systems, not just documents a business physically produces on request. This mirrors an international pattern already visible elsewhere in this tracker: the UK''s Making Tax Digital already requires digital records and API-based filing, and Greece''s myDATA platform aggregates real-time invoice and bookkeeping data centrally. Sweden''s move sits on the same trajectory — from static, document-based audits toward direct, system-to-system access.</p>
<p>Worth being precise about the relationship to e-invoicing specifically: Sweden still has no domestic B2B e-invoicing mandate, and the special investigator examining that question isn''t due to report until November 2027. But this online-audit development is likely to influence that eventual outcome in a genuinely practical way — if Sweden does introduce structured e-invoicing or near-real-time reporting later, the same cloud platforms and APIs already being built for online audit access could plausibly support e-invoicing too, reducing the need for entirely separate interfaces and specifications built independently of each other.</p>
<p><strong>What this means for your team:</strong> if your business keeps accounting records in cloud-based systems, confirm you understand what direct online access actually means for Skatteverket''s inspection capability going forward — this is a genuinely different access model than the traditional request-and-produce audit process. Given this infrastructure may end up underpinning any future e-invoicing requirement too, it''s worth treating as connected to the broader digitalisation direction rather than an isolated audit-powers change.</p>', 'https://www.skatteverket.se', 1);
INSERT INTO story_countries (story_id, country_id) SELECT '2026-05-06-sweden-online-audit-powers', id FROM countries WHERE name_en = 'Sweden';
INSERT INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-05-06-sweden-online-audit-powers', 'en', 'Parliament approves direct online access to accounting records for Skatteverket', 'Sweden''s Parliament approved government proposals granting Skatteverket the power to inspect businesses'' accounting and other records directly via the internet, including records held in cloud platforms or third-party systems — a step toward system-to-system tax administration even without a formal e-invoicing mandate yet.', '<h3>🇸🇪 Parliament approves direct online access to accounting records for Skatteverket</h3>
<p>Sweden''s Parliament approved government proposals granting Skatteverket the power to inspect businesses'' accounting and other accounting material directly via the internet — including records held on cloud platforms or in third-party systems, not just documents a business physically produces on request. This mirrors an international pattern already visible elsewhere in this tracker: the UK''s Making Tax Digital already requires digital records and API-based filing, and Greece''s myDATA platform aggregates real-time invoice and bookkeeping data centrally. Sweden''s move sits on the same trajectory — from static, document-based audits toward direct, system-to-system access.</p>
<p>Worth being precise about the relationship to e-invoicing specifically: Sweden still has no domestic B2B e-invoicing mandate, and the special investigator examining that question isn''t due to report until November 2027. But this online-audit development is likely to influence that eventual outcome in a genuinely practical way — if Sweden does introduce structured e-invoicing or near-real-time reporting later, the same cloud platforms and APIs already being built for online audit access could plausibly support e-invoicing too, reducing the need for entirely separate interfaces and specifications built independently of each other.</p>
