INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-06-01-sweden-peppol-authority-transfer', '2026-06-01', '2026-06', 'Digg, Sweden''s digitalisation agency and current Peppol Authority, is set to merge into PTS by 1 January 2027 as part of a wider government reorganisation — with the merged organisation expected to inherit Digg''s Peppol Authority responsibilities going forward.', '<h3>🇸🇪 Sweden''s Peppol Authority function set to transfer as Digg merges into PTS</h3>
<p>A planned government reorganisation will see Digg, Sweden''s digitalisation agency, cease to exist as a standalone authority by 1 January 2027, with its functions incorporated into PTS (the Swedish Post and Telecom Authority) as part of a new, merged digitalisation agency. This matters directly for e-invoicing infrastructure specifically: Digg currently serves as Sweden''s Peppol Authority, the body responsible for governing Peppol network participation and standards within the country, and the merged organisation is expected to assume this responsibility going forward.</p>
<p>Administrative reorganisations like this don''t typically change underlying technical requirements, but they''re genuinely worth tracking for businesses and solution providers with an established relationship with Digg specifically — points of contact, guidance documentation, and any ongoing correspondence tied to Digg as an institution may need to transition to whatever the merged authority is named and structured as, even if the actual Peppol rules and technical standards themselves remain unchanged.</p>
<p><strong>What this means for your team:</strong> if your business or software provider has any direct relationship with Digg specifically regarding Peppol connectivity or guidance, it''s worth confirming ahead of January 2027 how that relationship transitions to the merged organisation, rather than discovering a stale point of contact only when you actually need support. This is an administrative transition rather than a substantive rule change, but administrative gaps during agency mergers are a genuinely common source of avoidable friction.</p>', 'https://www.skatteverket.se', 1);
INSERT INTO story_countries (story_id, country_id) SELECT '2026-06-01-sweden-peppol-authority-transfer', id FROM countries WHERE name_en = 'Sweden';
